--- a/18-collapsible-tree-search.html
+++ b/18-collapsible-tree-search.html
@@ -461,20 +461,17 @@

   const transitionDur = dur(500);
   const t = svgEl.transition().duration(transitionDur);
+  const snap = (x, y) => { const o = {x, y}; return diagonal({source: o, target: o}); };

   // ── Links ──
   linkGroup.selectAll("path.link")
     .data(links, d => d.target.data.name + d.target.depth)
     .join(
       enter => enter.append("path")
-        .attr("d", () => {
-          const o = { x: source.x0 ?? source.x, y: source.y0 ?? source.y };
-          return diagonal({ source: o, target: o });
-        }),
+        .attr("d", () => snap(source.x0 ?? source.x, source.y0 ?? source.y)),
       update => update,
       exit => exit.transition(t)
-        .attr("d", () => diagonal({ source: { x: source.x, y: source.y }, target: { x: source.x, y: source.y } }))
-        .remove()
+        .attr("d", () => snap(source.x, source.y)).remove()
     )
     .attr("class", d => "link" + (pathSet.has(d.source) && pathSet.has(d.target) ? " highlight" : ""))
     .transition(t)
@@ -568,17 +565,12 @@

 // ── Tooltip ──
 function showTooltip(event, d) {
-  const rank = d.data.rank || "";
   const desc = countDescendants(d);
-  const state = d._children ? "collapsed" : d.children ? "expanded" : "leaf";
+  const leaf = !d.children && !d._children;
   tooltip.html(`
     <div class="tt-name">${d.data.name}</div>
-    <div class="tt-rank">${rank} (depth ${d.depth})</div>
-    <div class="tt-desc">${
-      state === "leaf" ? "Leaf node"
-      : state === "collapsed" ? `${desc} descendants (collapsed)`
-      : `${desc} descendants`
-    }</div>
+    <div class="tt-rank">${d.data.rank || ""} (depth ${d.depth})</div>
+    <div class="tt-desc">${leaf ? "Leaf node" : `${desc} descendants${d._children ? " (collapsed)" : ""}`}</div>
   `).style("opacity", 1);
 }
